function clamp(v:number,min:number,max:number){return Math.max(min,Math.min(max,v));}
function hashString(value:string){let h=0;for(let i=0;i<value.length;i++)h=(h*31+value.charCodeAt(i))|0;return Math.abs(h);}
function traitValue(id:string,key:string,min=18,max=92){return min+hashString(`${id}-${key}`)%(max-min+1);}
function lifeTraitsFor(id:string,personality:Personality):LifeTraits{const traits:LifeTraits={workEthic:traitValue(id,"work"),sociability:traitValue(id,"social"),laziness:traitValue(id,"lazy",8,74),bravery:traitValue(id,"brave"),curiosity:traitValue(id,"curious"),alcoholPreference:traitValue(id,"ale",4,88),musicPreference:traitValue(id,"music"),shoppingPreference:traitValue(id,"shop")};if(personality==="성실함"){traits.workEthic=Math.max(78,traits.workEthic);traits.laziness=Math.min(25,traits.laziness);}if(personality==="게으름"){traits.laziness=Math.max(76,traits.laziness);traits.workEthic=Math.min(42,traits.workEthic);}if(personality==="술 좋아함")traits.alcoholPreference=Math.max(82,traits.alcoholPreference);if(personality==="활발함")traits.sociability=Math.max(72,traits.sociability);if(personality==="겁 많음")traits.bravery=Math.min(28,traits.bravery);return traits;}
