  for(const candidate of candidates){if(["tavern","cafe","bakery","market"].includes(candidate.key)){if(beginVisit(v,model,candidate.key as BuildingKind)){recordEveningChoice(model,v,candidate.key);return;}}else if(candidate.key==="watch"&&performer&&beginWatching(v,model,performer))return;else if(candidate.key==="friend"&&friend&&!friend.visitKind&&friend.lifeState!=="TALK"){beginConversation(v,friend,model);recordEveningChoice(model,v,"talk");return;}else if(candidate.key==="garden"){const garden=findBuilding(model,"garden");if(garden){routeTo(v,buildingPoint(garden,"sit",hashString(v.id)%2),"rest",false,"REST");v.event="공동 정원에서 꽃과 작은 돌을 구경하며 쉬어요.";recordEveningChoice(model,v,"garden");return;}}else if(candidate.key==="stroll"){routeTo(v,{x:v.x+(hashString(`${v.id}-${v.step}`)%340)-170,y:BUILDING_BASELINE},"walk",false,"IDLE");v.event="마을 길을 천천히 산책하며 가게를 구경해요.";recordEveningChoice(model,v,"stroll");return;}else if(candidate.key==="home"&&home){routeTo(v,buildingPoint(home,"sit",hashString(v.id)%2),"rest",false,"REST","RETURN_HOME");v.event="자기 집으로 돌아가 잠들기 전 조용히 쉬어요.";recordEveningChoice(model,v,"home");return;}}
