  if(v.isVisitor){const market=findBuilding(model,"market");if(v.visitorDay!==model.day||minute>=(v.visitorDepartMinute??1100)){routeTo(v,{x:SURFACE_NAV.maxX-20,y:BUILDING_BASELINE},"walk",false,"IDLE");v.event="장사를 마치고 마을 가장자리로 걸어 나가요.";if(Math.abs(v.x-(SURFACE_NAV.maxX-20))<8)v.visitorDone=true;}else if(market)routeTo(v,buildingPoint(market,"sit",3),"chat",false,"SHOP");return;}
