const MILITARY_EQUIPMENT:Partial<Record<JobId,[EquipmentId|null,EquipmentId|null]>>={SOLDIER:["sword",null],SPEARMAN:["spear",null],ARCHER:["bow",null],KNIGHT:["sword","shield"],GUARD:["spear",null],AXEMAN:["axe",null],CROSSBOW:["crossbow",null],CAPTAIN:["sword","shield"],SHIELDER:["sword","shield"],HUNTER:["bow",null],SLINGER:["sling",null],SCOUT:["sword",null],BANNER:["banner",null],DRUMMER:["drum",null]};
function equipmentFor(v:Pick<Villager,"jobId"|"mode"|"carrying">&Partial<Pick<Villager,"carryingOreKind"|"nextMode"|"lifeState"|"isCivilian">>,minutes=12*60):[EquipmentId|null,EquipmentId|null]{
  if(v.isCivilian)return[null,null];
  if(isMountedJob(v.jobId))return[null,null];
  if(v.mode==="climb"||v.mode==="sleep"||v.mode==="rest"||v.mode==="chat"||v.mode==="listen"||v.mode==="goof"||v.mode==="queue"||v.mode==="order")return[null,null];
  if(v.mode==="drink")return["beer",null];if(v.mode==="eat")return["bread",null];if(v.carrying==="wood")return["wood",null];
  if(v.carryingOreKind||v.carrying==="stone"||v.carrying==="metal"||v.carrying==="crystal")return[null,null];
  const armed=MILITARY_EQUIPMENT[v.jobId];if(armed&&(v.mode==="walk"||v.mode==="patrol"||v.mode==="combat"))return armed;
  if((hourOf(minutes)>=18||hourOf(minutes)<7)&&v.mode!=="combat")return[null,null];
  const map:Partial<Record<JobId,[EquipmentId|null,EquipmentId|null]>>={MINER:["pickaxe",null],LUMBERJACK:["axe",null],PORTER:["sack",null],BUILDER:["wood-hammer",null],FARMER:["farming",null],...MILITARY_EQUIPMENT,BLACKSMITH:["smith-hammer",null],MASON:["wood-hammer",null],COOK:["bread",null],FISHER:["fishing-rod",null],TAILOR:["sack",null],MERCHANT:["book",null],GARDENER:["farming",null],HEALER:["cross",null],ENGINEER:["wood-hammer",null],BAKER:["bread",null],BREWER:["beer",null],CARPENTER:v.mode==="carry"?["wood",null]:["wood-hammer",null],MINSTREL:["guitar",null],PRIEST:["cross",null],SCHOLAR:["book",null],POTTER:["pottery",null],INNKEEPER:v.mode==="work"?["beer",null]:["lantern",null]};
  const commutingToWork=v.mode==="walk"&&(v.nextMode==="work"||v.nextMode==="heal"||v.lifeState==="GO_TO_WORK");
  if(v.mode==="walk"&&!commutingToWork)return[null,null];
  return map[v.jobId]??[null,null];
}
function villagerMoving(v:Pick<Villager,"x"|"y"|"targetX"|"targetY">){return Math.hypot(v.targetX-v.x,v.targetY-v.y)>4;}
function characterStateFor(v:Villager):CharacterState{
  if(v.combatState==="DOWN")return"IDLE";
  if(v.combatState==="ATTACK")return"ATTACK";
  if(v.combatState==="AIM")return"AIM";
  if(v.combatState==="DEFEND")return"DEFEND";
  if(villagerMoving(v))return"WALK";
  if(v.mode==="work"||v.mode==="heal")return"WORK";
  if(v.mode==="carry")return"CARRY";
  if(v.mode==="eat")return"EAT";
  if(v.mode==="drink")return"DRINK";
  if(v.mode==="chat"||v.mode==="listen"||v.mode==="goof")return"TALK";
  if(v.mode==="sleep")return"SLEEP";
  if(v.mode==="combat"){
    if(RANGED_JOBS.has(v.jobId))return v.shotPending||v.releaseTimer>0?"AIM":"IDLE";
    if(v.jobId==="SHIELDER"&&!v.shotPending&&!v.releaseTimer)return"DEFEND";
    return v.shotPending||v.releaseTimer>0?"ATTACK":"IDLE";
  }
  return"IDLE";
}
function transitionCharacterState(v:Villager,next:CharacterState,dt:number){if(v.characterState!==next){v.characterState=next;v.characterStateTime=0;}else v.characterStateTime+=dt;}
function syncCharacterState(v:Villager,dt:number){transitionCharacterState(v,characterStateFor(v),dt);}
function canAfford(r:Resources,c:Partial<Resources>){return(Object.keys(c) as ResourceKey[]).every((k)=>r[k]>=(c[k]??0));}
function spend(r:Resources,c:Partial<Resources>){(Object.keys(c) as ResourceKey[]).forEach((k)=>r[k]-=c[k]??0);}

