  const [worldW,worldH]=buildingDimensions(kind),canvas=document.createElement("canvas"),pixelStep=2.6,maxW=Math.max(30,Math.round(worldW/pixelStep)),maxH=Math.max(24,Math.round(worldH/pixelStep)),scale=Math.min(maxW/image.width,maxH/image.height);canvas.width=Math.max(12,Math.round(image.width*scale));canvas.height=Math.max(12,Math.round(image.height*scale));const sprite=canvas.getContext("2d",{willReadFrequently:true});if(!sprite)return canvas;
