function pixelBuildingTheme(kind:BuildingKind){
  if(kind==="smithy")return{wall:"#756150",roof:"#403d37",trim:"#b36f3d"};if(kind==="hospital")return{wall:"#d6d2ae",roof:"#708565",trim:"#9c4f46"};if(kind==="cafe")return{wall:"#d9b985",roof:"#8f6847",trim:"#b96f55"};if(kind==="tavern")return{wall:"#a7794f",roof:"#5d4537",trim:"#d2a05c"};if(kind==="bakery")return{wall:"#d7b477",roof:"#a25f3f",trim:"#f0cf85"};if(kind==="barracks"||kind==="watchtower")return{wall:"#96836a",roof:"#4e5548",trim:"#bd7446"};if(kind==="warehouse"||kind==="logistics")return{wall:"#92704e",roof:"#57463a",trim:"#c69b61"};if(kind==="market")return{wall:"#c99a63",roof:"#765b3f",trim:"#d97853"};return{wall:"#c5a876",roof:"#72513b",trim:"#d99a57"};
}
