  ctx.save();ctx.imageSmoothingEnabled=false;if(selected){ctx.strokeStyle="#f3cf69";ctx.lineWidth=2;ctx.strokeRect(left-3,top-3,drawW+6,drawH+5);}if(!buildingIsComplete(b)){const progress=clamp(b.constructionProgress,0,1),revealH=Math.max(2,Math.round(drawH*progress));ctx.globalAlpha=.14;ctx.drawImage(sprite,left,top,drawW,drawH);ctx.save();ctx.beginPath();ctx.rect(left,ground-revealH,drawW,revealH);ctx.clip();ctx.globalAlpha=1;ctx.drawImage(sprite,left,top,drawW,drawH);ctx.restore();ctx.globalAlpha=1;ctx.fillStyle="#2b2b35";ctx.fillRect(left,ground+2,drawW,3);ctx.fillStyle="#e0bf65";ctx.fillRect(left,ground+2,Math.round(drawW*progress),3);}else ctx.drawImage(sprite,left,top,drawW,drawH);if(night){ctx.globalCompositeOperation="multiply";ctx.fillStyle="rgba(88,92,116,.16)";ctx.fillRect(left,top,drawW,drawH);ctx.globalCompositeOperation="source-over";}if(buildingIsComplete(b)&&b.level>1)drawBuildingUpgradeProps(ctx,b,{x:left,y:ground},drawW,drawH,z);if((b.hp??180)<(b.maxHp??180)){ctx.strokeStyle="#b86855";ctx.lineWidth=Math.max(1,z);ctx.beginPath();ctx.moveTo(left+drawW*.72,ground-drawH*.32);ctx.lineTo(left+drawW*.64,ground-drawH*.48);ctx.lineTo(left+drawW*.74,ground-drawH*.61);ctx.stroke();}if((b.damageFlash??0)>0){ctx.fillStyle="rgba(255,203,112,.42)";ctx.fillRect(left,top,drawW,drawH);}ctx.restore();
