function drawQuarryPixelBlock(ctx:CanvasRenderingContext2D,left:number,top:number,size:number,color:string,_highlight=.42){const x=Math.round(left),y=Math.round(top),s=Math.max(2,Math.round(size));ctx.fillStyle=color;ctx.fillRect(x,y,s,s);}
